"""Celestial Familiars ImageGen sheets: one 4x3 pose sheet per hero beast (idle x4, move x4, windup / strike / recover / hit) plus one 3x4 effect sheet. Run: python art/fam/run.py [name...]; process.py cuts them into public/art/fam."""
import subprocess, os, concurrent.futures as cf
env = dict(os.environ); env['CODEX_BIN'] = r'C:\Program Files\WindowsApps\OpenAI.Codex_26.1111.2228.0_x64__2p2nqsd0c76g0\app\resources\codex.exe'
D = 'art/fam'
SHEET = ("A pose sheet for ONE small companion creature, a cute-but-fierce chibi sidekick version of the attached reference beast (same design language, palette, and material), drawn in the same hand-painted premium 2D game style with crisp bold silhouettes and rim light. Exactly 12 poses in a clean 4 columns by 3 rows grid, every pose the SAME creature at the SAME size and the same design, SIDE VIEW facing RIGHT, each fully inside its own cell with generous pure black margin, nothing touching the cell edges. Row 1: four IDLE poses (calm hover/stand, small breathing and wing or tail sway differences so they loop). Row 2: four MOVE poses (a fast forward run/flight cycle, limbs and wings or tails in four distinct phases). Row 3: pose 9 ATTACK WINDUP (coiled back, gathering energy), pose 10 ATTACK STRIKE (lunging forward, mouth or claws open, motion lines allowed), pose 11 ATTACK RECOVER (following through, settling), pose 12 HIT REACTION (flinching backward, eyes shut). PURE BLACK (#000000) background, no ground, no scenery, no cast shadow, absolutely no text, letters, numbers, grid lines, logo or watermark. Original design. ")
J = {
 'dragon': (SHEET + "The creature: a small SOLAR DRAGON WYRMLING, body about the size of a large cat, two small articulated wings, short swept horns, a long curling tail ending in a flame tuft, golden-orange scales with a cream belly, glowing amber eyes and ember glints. Palette: molten orange, gold, cream, a little red; NOT blue, NOT purple.", ['public/ui/hud/beast_flare.webp']),
 'fox': (SHEET + "The creature: a small SPECTRAL NINE-TAILED FOX KIT, slim and agile, charcoal-black ash fur with pale ivory rim light, thin glowing orange fissures, glowing orange eyes, a small black eclipse disc with an orange corona on the chest, and nine short readable tails fanned behind it. Palette: obsidian charcoal, pale bone ash, burnt orange embers; NOT bright red, NOT blue.", ['public/ui/hud/beast_fox.webp', 'public/ui/hud/beast_ashfox.webp']),
 'phoenix': (SHEET + "The creature: a small PHOENIX FLEDGLING, graceful and radiant, luminous cream and mother-of-pearl feathers with pale rose tips and dusk-violet feather edges, a glowing star core at the breast, a crested head with an open beak, two articulated feathered wings, and three long trailing constellation tail streamers with tiny four-pointed stars. Palette: cream pearl, pale rose, dusk violet, thin aqua-pink-gold prism edge light; NOT blue, NOT plain white, NOT red.", ['public/ui/hud/beast_phoenix.webp', 'public/ui/hud/beast_eventide.webp']),
 'guardian': (SHEET + "The creature: a small ABYSSAL GUARDIAN, a compact armored void drake-sentinel built from layered dark shard plates, slightly heavier and more solid than the others, horned and crested head with a pale lavender glowing eye slit, spiked tail curling, clawed forelimbs, small jagged shard wings, thin pale lavender energy cracks running over deep violet-black plating. Palette: near-black violet, deep purple, pale lavender highlights; NOT blue, NOT pink, NOT red.", ['public/ui/hud/beast_guard1.webp']),
 'fx': ("Companion-beast combat effect sprites for a premium anime action game, hand-painted 2D, razor-sharp shapes, bright cores with a luminous edge, readable at 100 pixels. TWELVE items in a clean 3 columns by 4 rows grid, one item per cell, each fully inside its cell with generous pure black margin. For each ROW: column 1 = an ATTACK PROJECTILE or STRIKE STREAK pointing RIGHT with a short trail; column 2 = an IMPACT BURST (radial starburst, front view); column 3 = a flat SUMMON SIGIL ring seen at an oblique angle (a glowing ring with small emblem marks, dark centre). ROW 1 SOLAR DRAGON: a flaming fireball with a draconic claw-slash trail, a golden-orange fire burst with ember sparks, a solar ring sigil with sun rays; palette molten orange, gold, cream. ROW 2 ASH FOX: a charcoal-and-ember crescent claw slash, an ash and ember burst with pale ivory sparks, an eclipse ring sigil with a black disc and orange corona; palette charcoal black, bone ash, burnt orange. ROW 3 PHOENIX: a luminous feather dart with a streak and star motes, a prism starburst of pearl shards, a halo ring sigil with four-pointed stars; palette cream pearl, pale rose, dusk violet, thin prism edges. ROW 4 VOID GUARDIAN: a violet void shard bolt with a dark core, a rift implosion burst with pale lavender cracks and shard fragments, a void rift ring sigil with angular shard marks; palette near-black violet, deep purple, pale lavender. PURE BLACK (#000000) background, no ground, no cast shadow, absolutely no text, letters, numbers, grid lines, logo or watermark. Original design.", ['public/ui/hud/beast_flare.webp']),
}
def run(n):
    pr, rf = J[n]; open(f'{D}/{n}-prompt.txt', 'w', encoding='utf-8').write(pr)
    cmd = ['python', 'scripts/gen-image.py', D, n]
    for r in rf: cmd += ['--img', r]
    r = subprocess.run(cmd, capture_output=True, text=True, env=env); return n, r.returncode, (r.stdout + r.stderr)[-160:]
if __name__ == '__main__':
    import sys
    with cf.ThreadPoolExecutor(5) as ex:
        for r in ex.map(run, sys.argv[1:] or list(J)): print(r, flush=True)
